task_context.problem_statement:
Suppose $\cos R = \frac{4}{9}$ in the diagram below.  What is $QS$?



[asy]

pair Q,R,S;

S = (0,0);

Q = (sqrt(65),0);

R = (sqrt(65),-4);

draw(S--Q--R--S);

draw(rightanglemark(S,Q,R,13));

label("$S$",S,NW);

label("$Q$",Q,NE);

label("$R$",R,SE);

label("$9$",(R+S)/2,SW);

[/asy]

